/// Cosine similarity in [0,1]-ish range; 1.0 == identical direction.
pub fn cosine_similarity(a: &[f64], b: &[f64]) -> f64 {
    if a.len() != b.len() || a.is_empty() {
        return 0.0;
    }
    let mut dot = 0.0;
    let mut m1 = 0.0;
    let mut m2 = 0.0;
    for i in 0..a.len() {
        dot += a[i] * b[i];
        m1 += a[i] * a[i];
        m2 += b[i] * b[i];
    }
    if m1 == 0.0 || m2 == 0.0 {
        return 0.0;
    }
    dot / (m1.sqrt() * m2.sqrt())
}

/// Euclidean distance between two vectors.
pub fn euclidean_distance(a: &[f64], b: &[f64]) -> f64 {
    a.iter()
        .zip(b.iter())
        .map(|(x, y)| (x - y) * (x - y))
        .sum::<f64>()
        .sqrt()
}

/// Dot product between two vectors.
pub fn dot_product(a: &[f64], b: &[f64]) -> f64 {
    a.iter().zip(b.iter()).map(|(x, y)| x * y).sum()
}

/// Distance wrapper honouring the AN5 distance metric names.
pub fn vector_distance(a: &[f64], b: &[f64], metric: &str) -> f64 {
    match metric.to_lowercase().as_str() {
        "euclidean" => euclidean_distance(a, b),
        "dot" => -dot_product(a, b),
        _ => 1.0 - cosine_similarity(a, b),
    }
}

